from pathlib import Path
import re
p=Path('index.html')
s=p.read_text(encoding='utf-8')
s=re.sub(r'<!-- pages-publish:[^>]+-->', '<!-- pages-publish: underwear-flow-v2-2026-08-25 -->', s, count=1)
# UI
pat=r'<div id="shortUnderwearBox" class="hidden">.*?<div id="shortNightrobeBox" class="hidden">'
ui='''<div id="shortUnderwearBox" class="hidden"><div class="notice ok"><b>الداخليات U.W</b><div style="margin-top:5px">ابدأ بالفئة: رجالي أو شبابي أو ولادي، ثم اختر ستاندر أو فرزاتشي حسب المتاح، ثم المنتج والمقاس.</div></div><div class="title" style="margin-top:14px">الفئة</div><div id="uwGenerationChoices" class="actions fixedChoices" style="justify-content:flex-start;flex-wrap:wrap"></div><div id="uwStyleArea" class="hidden"><div class="title" style="margin-top:14px">النوع</div><div id="uwStyleChoices" class="actions fixedChoices" style="justify-content:flex-start;flex-wrap:wrap"></div></div><div id="uwProductArea" class="hidden"><div class="title" style="margin-top:14px">المنتج</div><div id="uwProductChoices" class="actions fixedChoices" style="justify-content:flex-start;flex-wrap:wrap"></div></div><div id="uwSizeArea" class="hidden"><div class="title" style="margin-top:14px">المقاس</div><div id="uwSizeChoices" class="actions fixedChoices" style="justify-content:flex-start;flex-wrap:wrap"></div></div><div id="uwSummary" class="notice" style="margin-top:14px">اختر الفئة.</div><div id="uwSelected" class="task hidden"><div class="fields"><div class="field"><label>الموجود حاليًا</label><input id="uwCurrent" inputmode="numeric" value="0"></div><div class="field"><label>المطلوب للتغذية</label><input id="uwRequested" inputmode="numeric" value="0"></div><div class="field"><label>الفرص الضائعة</label><input id="uwLost" inputmode="numeric" value="0"></div></div><div class="actions" style="justify-content:flex-start"><button class="btn" onclick="addUwDraft()">إضافة للنواقص</button></div></div><div class="title" style="margin-top:18px">طلب الداخليات الحالي</div><div id="uwDraftList"><p class="mut">لم تتم إضافة أصناف بعد.</p></div><div class="actions"><span></span><button class="btn gold" onclick="saveUwShortages()">حفظ نواقص الداخليات</button></div></div><div id="shortNightrobeBox" class="hidden">'''
s,n=re.subn(pat,ui,s,count=1,flags=re.S); assert n==1,'UW UI block not found'
# constants
pat=r"const UW_GENERATION_AR=\{Men:'رجالي',Youth:'شبابي',Boys:'ولادي'\};const UW_MAP=\{.*?\};const EGAL_BOYS_SIZES="
consts="""const UW_GENERATION_AR={Men:'رجالي',Youth:'شبابي',Boys:'ولادي'};const UW_FLOW={Men:{'ستاندر':{'فنيلة رقبة دائرية':['S','M','L','XL','XXL','XXXL'],'فنيلة رقبة عالية':['S','M','L','XL','XXL','XXXL'],'فنيلة كت':['S','M','L','XL','XXL','XXXL'],'سروال داخلي':['S','M','L','XL','XXL','XXXL'],'سروال طويل':['18K','18K-XXL','20K','20K-XXL','20R','22K','22R','24K','24R','26K','26R','28K','28R','30K','30K-XXL','S','M','L','XL','XXL','XXXL']},'فرزاتشي':{'فنيلة':['S','M','L','XL','XXL','XXXL'],'سروال داخلي':['S','M','L','XL','XXL','XXXL']}},Youth:{'ستاندر':{'طقم فنيلة وسروال':['9 - 10','11 - 12','13 - 14','15 - 16'],'سروال طويل':['30K','30R','32K','32R','34K','34R','36K','36R','38K','38R']}},Boys:{'ستاندر':{'طقم فنيلة وسروال':['1 - 2','3 - 4','5 - 6','7 - 8'],'سروال طويل':['16R','18R','20R','22R','24R','26K','26R','28K','28R','29K','29R']}}};const EGAL_BOYS_SIZES="""
s,n=re.subn(pat,consts,s,count=1,flags=re.S); assert n==1,'UW constants not found'
# functions
pat=r'function uwProducts\(\).*?function renderNightrobeControls\(\)'
funcs="""function uwGenerations(){return ['Men','Youth','Boys']}function uwStyles(){return uwGeneration?Object.keys(UW_FLOW[uwGeneration]||{}):[]}function uwProducts(){return uwGeneration&&uwStyle?Object.keys(UW_FLOW[uwGeneration]?.[uwStyle]||{}):[]}function renderUwControls(){$('uwGenerationChoices').innerHTML=uwGenerations().map(v=>`<button class=\"mini ${uwGeneration===v?'on':''}\" onclick=\"selectUwGeneration('${v}',this)\">${esc(UW_GENERATION_AR[v]||v)}</button>`).join('');let styles=uwStyles();$('uwStyleArea').classList.toggle('hidden',!uwGeneration);$('uwStyleChoices').innerHTML=styles.map(v=>`<button class=\"mini ${uwStyle===v?'on':''}\" onclick=\"selectUwStyle('${v}',this)\">${esc(v)}</button>`).join('');let products=uwProducts();$('uwProductArea').classList.toggle('hidden',!uwStyle);$('uwProductChoices').innerHTML=products.map(v=>`<button class=\"mini ${uwProduct===v?'on':''}\" onclick=\"selectUwProduct('${v}',this)\">${esc(v)}</button>`).join('');let sizes=uwGeneration&&uwStyle&&uwProduct?(UW_FLOW[uwGeneration]?.[uwStyle]?.[uwProduct]||[]):[];$('uwSizeArea').classList.toggle('hidden',!uwProduct);$('uwSizeChoices').innerHTML=sizes.map(v=>`<button class=\"mini ${uwSize===v?'on':''}\" onclick=\"selectUwSize('${v}',this)\">${esc(v)}</button>`).join('');updateUwSummary()}function selectUwGeneration(v,b){uwGeneration=v;uwStyle='';uwProduct='';uwSize='';renderUwControls()}function selectUwStyle(v,b){uwStyle=v;uwProduct='';uwSize='';renderUwControls()}function selectUwProduct(v,b){uwProduct=v;uwSize='';renderUwControls()}function selectUwSize(v,b){uwSize=v;renderUwControls()}function uwCurrentLabel(){if(!uwGeneration||!uwStyle||!uwProduct||!uwSize)return'';return `${UW_GENERATION_AR[uwGeneration]||uwGeneration} — ${uwStyle} — ${uwProduct} — ${uwSize}`}function updateUwSummary(){let label=uwCurrentLabel();if(label){$('uwSummary').innerHTML=`المحدد: <b>${esc(label)}</b>`;$('uwSelected').classList.remove('hidden');$('uwCurrent').value='0';$('uwRequested').value='0';$('uwLost').value='0';return}let msg='اختر الفئة.';if(uwGeneration&&!uwStyle)msg='اختر النوع.';else if(uwStyle&&!uwProduct)msg='اختر المنتج.';else if(uwProduct&&!uwSize)msg='اختر المقاس.';$('uwSummary').textContent=msg;$('uwSelected').classList.add('hidden')}function addUwDraft(){try{let label=uwCurrentLabel();if(!label)throw Error('أكمل اختيار الصنف');let section=$('shortSection').value,key=label.trim().toLowerCase(),dup=shortagesData.find(q=>{if(q.section_id!==section||String(q.size||'').trim().toLowerCase()!==key||q.shortage_status!=='تم الطلب')return false;let a=q.action_id?app.actions.find(z=>z.id===q.action_id):null;return !a||a.action_status!=='مغلق'});if(dup)throw Error(`هذا الصنف له طلب تغذية قائم بالفعل منذ ${dup.ordered_date||'—'}`);if(uwDraft.some(x=>x.label.trim().toLowerCase()===key))throw Error('هذا الصنف مضاف بالفعل في الطلب الحالي');let current=Number($('uwCurrent').value||0),requested=Number($('uwRequested').value||0),lost=Number($('uwLost').value||0);if([current,requested,lost].some(x=>Number.isNaN(x)||x<0))throw Error('أدخل الكميات بشكل صحيح');uwDraft.push({label,current_qty:current,requested_qty:requested,lost_opportunities:lost});renderUwDraft();$('uwCurrent').value='0';$('uwRequested').value='0';$('uwLost').value='0'}catch(e){alert(e.message)}}function removeUwDraft(i){uwDraft.splice(i,1);renderUwDraft()}function renderUwDraft(){$('uwDraftList').innerHTML=uwDraft.length?uwDraft.map((x,i)=>`<div class=\"task\"><b>${esc(x.label)}</b><div class=\"mut\" style=\"margin-top:6px\">الموجود: ${x.current_qty} | المطلوب: ${x.requested_qty} | الفرص الضائعة: ${x.lost_opportunities}</div><div style=\"margin-top:8px\"><button class=\"mini\" style=\"color:#c83b3b;border-color:#efb4b4\" onclick=\"removeUwDraft(${i})\">حذف</button></div></div>`).join(''):'<p class=\"mut\">لم تتم إضافة أصناف بعد.</p>'}function renderNightrobeControls()"""
s,n=re.subn(pat,funcs,s,count=1,flags=re.S); assert n==1,'UW functions not found'
p.write_text(s,encoding='utf-8')
